/* Radio button item */
.radio-button-group .radio-button-item {
  display: block;
  position: relative;
  padding-left: 18px;
  margin-bottom: 5px;
  cursor: pointer;
  font-weight: normal;
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

/* Hide the browser's default radio button */
.radio-button-group .radio-button-item input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

/* Custom radio button style */
.radio-button-group .checkmark {
  position: absolute;
  top: 2px;
  left: 0px;
  height: 14px;
  width: 14px;
  background-color: #fff;
  border-radius: 50%;
  border: 1px solid #ccc;
}

/* Indicator style */
.radio-button-group .radio-button-item .checkmark:after {
  top: 2px;
  left: 2px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  content: "";
  position: absolute;
  display: block;
  transition: background-color 0.3s ease-in-out;
}

/* Indicator for checked */
.radio-button-group .radio-button-item input:checked ~ .checkmark:after {
  display: block;
  background-color: #4399fa;
}

/* Indicator for checked */
.radio-button-group .radio-button-item input.checked ~ .checkmark:after {
  display: block;
  background-color: #4399fa;
