.nano {
  position : relative;
  width    : 100%;
  height   : 100%;
  overflow : hidden;
}
.nano > .nano-content {
  position      : absolute;
  overflow      : scroll;
  overflow-x    : hidden;
  top           : 0;
  right         : 0;
  bottom        : 0;
  left          : 0;
}
.nano > .nano-content:focus {
  outline: thin dotted;
}
.nano > .nano-content::-webkit-scrollbar {
  display: none;
}
.has-scrollbar > .nano-content::-webkit-scrollbar {
  display: block;
}
.nano > .nano-pane {
  position   : absolute;
  width      : 7px;
  right      : 1px;
  top        : 0;
  bottom     : 0;
}

.nano > .nano-pane > .nano-slider {
  background: transparent;
  position              : relative;
  border-radius: 4px;
}

.nano:hover > .nano-pane > .nano-slider {
  background: #aaa;
}

.nano > .nano-pane > .nano-slider:active,
.nano:hover > .nano-pane > .nano-slider:hover {
  background: #999;
}
