@keyframes click_effect {
    50% {
        transform: scale(1.5, 1.5);
        opacity: 0;
    }
    99% {
        transform: scale(0.001, 0.001);
        opacity: 0;
    }
    100% {
        transform: scale(0.001, 0.001);
        opacity: 1;
    }
}

@keyframes pulse_effect {
    0% {
        opacity: 1;
    }
    50% {
        opacity: 0.2;
    }
    100% {
        opacity: 1;
    }
}

@keyframes rotate_effect {
    from {
        transform: rotate(0deg) translate(-25%) rotate(0deg);
    }
    to {
        transform: rotate(360deg) translate(-25%) rotate(-360deg);
    }
}

@keyframes move_h_effect {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-25%);
    }
    100% {
        transform: translateY(0);
    }
}

@keyframes move_h_large_effect {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-130%);
    }
    100% {
        transform: translateY(0);
    }
}

@keyframes move_w_effect {
    0% {
        transform: translateX(0);
    }
    50% {
        transform: translateX(-25%);
    }
    100% {
        transform: translateX(0);
    }
}

@keyframes move_w_large_effect {
    0% {
        transform: translateX(0);
    }
    50% {
        transform: translateX(-130%);
    }
    100% {
        transform: translateX(0);
    }
}

@keyframes move_effect {
    0% {
        transform: translate(0,0);
    }
    50% {
        transform: translate(-25%, -25%);
    }
    100% {
        transform: translate(0, 0);
    }
}

@keyframes scale_effect {
    0% {
        transform: scale(1, 1);
    }
    50% {
        transform: scale(0.75, 0.75);
    }
    100% {
        transform: scale(1, 1);
    }
}

